const str=(x,n=200)=>typeof x==='string'&&x.length<=n;
const integer=(x,min=0,max=1e12)=>Number.isSafeInteger(x)&&x>=min&&x<=max;
const date=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(new Date(x+'T12:00:00Z'))&&new Date(x+'T12:00:00Z').toISOString().slice(0,10)===x;
const fail=msg=>{throw Error('進階資料不正確：'+msg)};
export function defaultFeatures(){return {schema:2,books:[{id:'personal',name:'生活'},{id:'work',name:'工作代墊'},{id:'business',name:'事業'}],categories:[],categoryBudgets:{},bookBudgets:{},cycleDay:1,plans:[],bills:[],reconciliations:[],trash:[]}}
export function validateFeatures(raw,accounts,rawTx=[]){if(!raw||raw.schema!==2)fail('版本');const f=defaultFeatures(),account=id=>accounts.some(a=>a.id===id),txIds=new Set(rawTx.map(t=>t.id));
 if(!Array.isArray(raw.books)||!raw.books.length||raw.books.length>30)fail('帳本');const ids=new Set();f.books=raw.books.map(b=>{if(!str(b.id,80)||!b.id||ids.has(b.id)||!str(b.name,40)||!b.name.trim())fail('帳本名稱或編號');ids.add(b.id);return {id:b.id,name:b.name}});if(!ids.has('personal'))fail('生活帳本缺少');
 if(!Array.isArray(raw.categories)||raw.categories.length>100||raw.categories.some(c=>!str(c,40)||!c.trim()||['__proto__','constructor','prototype'].includes(c))||new Set(raw.categories).size!==raw.categories.length)fail('自訂分類');f.categories=[...raw.categories];if(!integer(raw.cycleDay,1,31))fail('月份起算日');f.cycleDay=raw.cycleDay;
 for(const key of ['categoryBudgets','bookBudgets']){for(const [period,limits] of Object.entries(raw[key]||{})){const split=period.lastIndexOf(':');if(!ids.has(period.slice(0,split))||!/^\d{4}-(0[1-9]|1[0-2])$/.test(period.slice(split+1)))fail('預算月份');if(key==='bookBudgets'){if(!integer(limits))fail('帳本預算');f[key][period]=limits}else{const row={};for(const [c,n] of Object.entries(limits)){if(!str(c,40)||!integer(n))fail('分類預算');Object.defineProperty(row,c,{value:n,enumerable:true,writable:true,configurable:true})}f[key][period]=row}}}
 const common=x=>{if(!x||!str(x.id,100)||!x.id||!str(x.name,200)||!x.name.trim()||!ids.has(x.bookId)||!account(x.account))fail('項目、帳本或帳戶');return {id:x.id,name:x.name,bookId:x.bookId,account:x.account}};
 if(!Array.isArray(raw.plans)||raw.plans.length>1000)fail('分期數量');const plans=new Set();f.plans=raw.plans.map(p=>{const r=common(p);if(plans.has(p.id)||!['card','bnpl'].includes(accounts.find(a=>a.id===p.account)?.kind)||!integer(p.totalPrincipal,1)||!integer(p.totalFee)||!integer(p.count,1,120)||p.count>p.totalPrincipal||!date(p.firstDue)||!date(p.purchaseDate)||!str(p.category,40)||!txIds.has(p.purchaseTxId)||!account(p.source))fail('分期方案');plans.add(p.id);Object.assign(r,{totalPrincipal:p.totalPrincipal,totalFee:p.totalFee,count:p.count,firstDue:p.firstDue,purchaseDate:p.purchaseDate,category:p.category,purchaseTxId:p.purchaseTxId,source:p.source,payments:[],refunds:[]});
 if(!Array.isArray(p.payments)||p.payments.length>2000||!Array.isArray(p.refunds)||p.refunds.length>1000)fail('還款或退款數量');const payIds=new Set();let paid=0,refunded=0;r.payments=p.payments.map(v=>{if(!str(v.id,100)||payIds.has(v.id)||!date(v.date)||!account(v.source)||!txIds.has(v.transferTxId)||!Array.isArray(v.allocations)||!v.allocations.length||v.allocations.length>120)fail('還款紀錄');payIds.add(v.id);const allocations=v.allocations.map(a=>{if(!integer(a.index,0,p.count-1)||!integer(a.principal)||!integer(a.fee))fail('還款分配');paid+=a.principal;return {index:a.index,principal:a.principal,fee:a.fee}});if(v.feeTxId!==null&&!txIds.has(v.feeTxId))fail('還款費用紀錄');return {id:v.id,date:v.date,source:v.source,allocations,transferTxId:v.transferTxId,feeTxId:v.feeTxId}});r.refunds=p.refunds.map(v=>{if(!str(v.id,100)||!integer(v.amount,1)||!date(v.date)||!txIds.has(v.txId))fail('退款');refunded+=v.amount;return {id:v.id,amount:v.amount,date:v.date,txId:v.txId}});if(paid>p.totalPrincipal||refunded>p.totalPrincipal)fail('累計本金超過原額');return r});
 if(!Array.isArray(raw.bills)||raw.bills.length>2000)fail('固定收支數量');const billids=new Set();f.bills=raw.bills.map(b=>{const r=common(b);if(billids.has(b.id)||!['expense','income','transfer'].includes(b.type)||!integer(b.amount,1)||!str(b.category,40)||!date(b.start)||!['monthly','weekly','yearly'].includes(b.interval)||typeof b.active!=='boolean'||(b.end!==null&&!date(b.end)))fail('固定收支');billids.add(b.id);if(b.type==='transfer'&&(!account(b.toAccount)||b.toAccount===b.account))fail('固定轉帳');return {...r,type:b.type,amount:b.amount,category:b.category,start:b.start,end:b.end,interval:b.interval,active:b.active,toAccount:b.type==='transfer'?b.toAccount:null}});
 if(!Array.isArray(raw.reconciliations)||raw.reconciliations.length>1000)fail('對帳數量');f.reconciliations=raw.reconciliations.map(r=>{if(!str(r.id,100)||!account(r.account)||!date(r.date)||!integer(r.actual,-1e12)||!integer(r.expected,-1e12)||!integer(r.difference,-1e12)||!str(r.note,200)||(r.txId!==null&&!txIds.has(r.txId)))fail('對帳紀錄');return {id:r.id,account:r.account,date:r.date,actual:r.actual,expected:r.expected,difference:r.difference,note:r.note,txId:r.txId}});
 if(!Array.isArray(raw.trash)||raw.trash.length>100)fail('回收桶數量');f.trash=raw.trash.map(v=>{if(!str(v.id,100)||!integer(v.deletedAt,0,9e15)||!v.tx)fail('回收桶');return {id:v.id,deletedAt:v.deletedAt,tx:structuredClone(v.tx)}});return f;
}
export function transactionMeta(t,state){const out={};if(t.bookId!==undefined){if(!state.features?.books.some(b=>b.id===t.bookId))fail('交易帳本');out.bookId=t.bookId}if(t.tags!==undefined){if(!Array.isArray(t.tags)||t.tags.length>20||t.tags.some(x=>!str(x,40)))fail('標籤');out.tags=[...new Set(t.tags)]}if(t.origin!==undefined){const o=t.origin;if(!o||!['planPurchase','planPayment','planFee','planRefund','bill','reconcile','advanceExpense','advanceOut','advanceReturn'].includes(o.kind)||!str(o.id,100)||(o.relatedId!==undefined&&!str(o.relatedId,100))||(o.occurrence!==undefined&&!str(o.occurrence,100)))fail('關聯');out.origin={kind:o.kind,id:o.id,...(o.relatedId!==undefined?{relatedId:o.relatedId}:{}),...(o.occurrence!==undefined?{occurrence:o.occurrence}:{})}}return out}
export function validateFeatureLinks(state){if(!state.features)return;const tx=new Map(state.transactions.map(t=>[t.id,t])),source=id=>{const a=state.accounts.find(a=>a.id===id);return a?.kind==='mobile'&&a.paymentMode==='linked'?a.linkedAccount:id};for(const p of state.features.plans){const purchase=tx.get(p.purchaseTxId);if(!purchase||purchase.type!=='expense'||purchase.amount!==p.totalPrincipal||source(purchase.account)!==p.account||purchase.origin?.kind!=='planPurchase'||purchase.origin.id!==p.id||source(p.source)===p.account)fail('分期消費或來源關聯');const rowPaid=Array(p.count).fill(0);for(const v of p.payments){let principal=0,fee=0;for(const a of v.allocations){principal+=a.principal;fee+=a.fee;rowPaid[a.index]+=a.principal}const transfer=tx.get(v.transferTxId);if(principal<=0||!transfer||transfer.type!=='transfer'||transfer.amount!==principal+fee||source(transfer.account)!==source(v.source)||source(transfer.toAccount)!==p.account||transfer.date!==v.date||transfer.origin?.kind!=='planPayment'||transfer.origin.id!==p.id||transfer.origin.relatedId!==v.id)fail('分期還款關聯');if(fee){const t=tx.get(v.feeTxId);if(!t||t.type!=='expense'||t.amount!==fee||source(t.account)!==p.account||t.origin?.kind!=='planFee'||t.origin.relatedId!==v.id)fail('分期費用關聯')}else if(v.feeTxId!==null)fail('零費用仍有費用關聯')}for(let i=0;i<p.count;i++)if(rowPaid[i]>Math.floor(p.totalPrincipal/p.count)+(i<p.totalPrincipal%p.count?1:0))fail('單期本金超額');for(const r of p.refunds){const t=tx.get(r.txId);if(!t||t.type!=='refund'||t.amount!==r.amount||source(t.account)!==p.account||t.date!==r.date||t.origin?.kind!=='planRefund'||t.origin.id!==p.id||t.origin.relatedId!==r.id)fail('分期退款關聯')}}const occurrences=new Set();for(const t of state.transactions.filter(t=>t.origin?.kind==='bill')){const o=t.origin,key=o.id+':'+o.occurrence;if(!state.features.bills.some(b=>b.id===o.id)||!date(o.occurrence)||occurrences.has(key))fail('固定收支期別重複或缺少');occurrences.add(key)}for(const r of state.features.reconciliations){if(r.actual-r.expected!==r.difference)fail('對帳差額');if(r.txId){const t=tx.get(r.txId);if(!t||t.amount!==Math.abs(r.difference)||t.type!==(r.difference>0?'income':'expense')||source(t.account)!==source(r.account)||t.origin?.kind!=='reconcile'||t.origin.id!==r.id)fail('對帳調整關聯')}}}
